public class NoContentFilterAttribute: Attribute, IAsyncActionFilter
{
    public async Task OnActionExecutionAsync(ActionExecutingContext context, ActionExecutionDelegate next)
    {
        //Do some things.
        await next();
        if (context.HttpContext.Response.StatusCode == 200 
            && context.ActionDescriptor is ControllerActionDescriptor controllerActionDescriptor 
            && (
                controllerActionDescriptor.MethodInfo.ReturnType == typeof(void)
                || controllerActionDescriptor.MethodInfo.ReturnType == typeof(Task)
            )
            && context.Result == null
        )
        {
            context.HttpContext.Response.StatusCode = 204;
        }
        //Do some things.
    }
}
public class ResultWrapperAttribute : ActionFilterAttribute
{
    public override void OnActionExecuted(ActionExecutedContext context)
    {
        context.Result = new ObjectResult(new ResultWrapper { Code = 200 });
        base.OnActionExecuted(context);
    }
}
public class ResultWrapper
{
    public int Code { get; set; }
    public string Message { get; set; }
    public object Data { get; set; }
}

